import csv,io,json,os,shutil,subprocess,sys,tempfile,hashlib,platform
SRC='products/sites/shopify-catalogue-example/'
OUT='products/services/catalogue-qa/fulfillment/'
os.makedirs(OUT,exist_ok=True)
d=tempfile.mkdtemp()
for f in ['transform.py','verify.py','verify_example.py']: shutil.copy(SRC+f,d)
hashes={f:hashlib.sha256(open(SRC+f,'rb').read()).hexdigest() for f in ['transform.py','verify.py','verify_example.py']}
VH='style_id,title,color,size,sku,barcode,price,vendor,product_type,tags'
var=[]
n=0
for sid,title,colors,sizes in [('SYN-A','Synthetic Boot A',['Black','Tan'],['40','41','42','43','44']),('SYN-B','Synthetic Bag B',['Red','Blue'],['S','M','L','XL','XXL'])]:
  for c in colors:
    for s in sizes:
      n+=1; var.append([sid,title,c,s,'%s-%s-%s'%(sid,c[:2].upper(),s),'0000000%06d'%n,'%d.00'%(50+n),'SynVendor','Shoes' if sid=='SYN-A' else 'Bags','synthetic'])
img=[]
for sid,colors in [('SYN-A',['Black','Tan']),('SYN-B',['Red','Blue'])]:
  p=0
  for c in colors:
    for k in range(2):
      p+=1; img.append([sid,c,str(p),'https://example.com/img/%s-%s-%d.jpg'%(sid,c,k+1)])
def wcsv(path,hdr,rows):
  with open(path,'w',newline='',encoding='utf-8') as f:
    w=csv.writer(f,lineterminator='\n'); w.writerow(hdr.split(',')); w.writerows(rows)
def run(args):
  r=subprocess.run([sys.executable,'-I']+args,cwd=d,capture_output=True,text=True)
  return {'argv':args,'exit':r.returncode,'stdout':r.stdout[-1500:],'stderr':r.stderr[-1500:]}
res={'label':'SYNTHETIC PREPARATION ONLY - no customer data, no customer, no order','runtime':{'python':platform.python_version(),'tool_hashes':hashes},'variant_rows':len(var),'image_rows':len(img),'cases':{}}
wcsv(d+'/v.csv',VH,var); wcsv(d+'/i.csv','style_id,color,position,url',img)
res['cases']['A_input_only_valid_transform']=run(['transform.py','--variants','v.csv','--images','i.csv','--out','ours.csv','--report','rep.json'])
res['cases']['A_input_only_valid_verify_our_output']=run(['verify_example.py','v.csv','i.csv','ours.csv'])
def incase(name,vm=None,im=None):
  v2=[list(r) for r in var]; i2=[list(r) for r in img]
  if vm: vm(v2)
  if im: im(i2)
  wcsv(d+'/v_%s.csv'%name,VH,v2); wcsv(d+'/i_%s.csv'%name,'style_id,color,position,url',i2)
  res['cases']['B_input_only_'+name]=run(['transform.py','--variants','v_%s.csv'%name,'--images','i_%s.csv'%name,'--out','o_%s.csv'%name,'--report','r_%s.json'%name])
def dupsku(v): v[1][4]=v[0][4]
def dupbc(v): v[1][5]=v[0][5]
def dupcs(v): v[1][3]=v[0][3]
def badprice(v): v[2][6]='12,50'
def badurl(i): i[0][3]='ftp://example.com/x.jpg'
def dupimg(i): i.append(list(i[0]))
incase('duplicate_sku',dupsku); incase('duplicate_barcode',dupbc); incase('duplicate_color_size',dupcs); incase('bad_price',badprice); incase('non_http_image',None,badurl); incase('duplicate_image_row',None,dupimg)
with open(d+'/ours.csv',newline='',encoding='utf-8') as f: rr=list(csv.reader(f))
hdr,body=rr[0],rr[1:]
H={h:k for k,h in enumerate(hdr)}
vrows=[k for k,r in enumerate(body) if r[H['SKU']]]
res['output_shape']={'rows':len(body),'variant_rows':len(vrows),'image_only_rows':sum(1 for r in body if not r[H['SKU']])}
def outcase(name,fn):
  b=[list(r) for r in body]; fn(b)
  with open(d+'/p_%s.csv'%name,'w',newline='',encoding='utf-8') as f:
    w=csv.writer(f,lineterminator='\n'); w.writerow(hdr); w.writerows(b)
  res['cases']['C_produced_'+name]=run(['verify_example.py','v.csv','i.csv','p_%s.csv'%name])
outcase('valid_unchanged',lambda b:None)
def m_bc(b): b[vrows[3]][H['Barcodes']]='9999999999999'
def m_pr(b): b[vrows[4]][H['Price']]='99.99'
def m_dup(b): b.insert(vrows[5]+1,list(b[vrows[5]]))
def m_img_missing(b):
  k=[j for j,r in enumerate(b) if r[H['Product image URL']]][-1]
  if b[k][H['SKU']]:
    b[k][H['Product image URL']]=''; b[k][H['Image position']]=''; b[k][H['Image alt text']]=''
  else: del b[k]
def m_varimg(b): b[vrows[6]][H['Variant image URL']]='https://example.com/img/other.jpg'
def m_unknown_sku(b): b[vrows[7]][H['SKU']]='NOT-IN-INPUT'
def m_drop_variant(b): del b[vrows[-1]]
for nm,fn in [('barcode_changed',m_bc),('price_changed',m_pr),('duplicate_variant_row',m_dup),('image_removed',m_img_missing),('wrong_variant_image',m_varimg),('unknown_sku',m_unknown_sku),('variant_row_dropped',m_drop_variant)]: outcase(nm,fn)
v21=var+[['SYN-B','Synthetic Bag B','Green','S','SYN-B-GR-S','0000000000099','70.00','SynVendor','Bags','synthetic']]
wcsv(d+'/v21.csv',VH,v21)
res['cases']['D_21_rows_transform']=run(['transform.py','--variants','v21.csv','--images','i.csv','--out','o21.csv','--report','r21.json'])
for f in ['v.csv','i.csv','ours.csv']: shutil.copy(d+'/'+f,OUT+'synthetic-'+f)
json.dump(res,open(OUT+'execution-results.json','w'),indent=1)
print(res['output_shape'])
for k,c in res['cases'].items():
  s=c['stdout']
  try: fl=json.loads(s).get('failed')
  except Exception: fl=s.strip()[:200].replace(chr(10),' ')
  print(k,'exit',c['exit'],'out',fl,'| err:',c['stderr'].strip().splitlines()[-1][:200] if c['stderr'].strip() else '')
